head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[group > E > onmouseout]<br/>컴포넌트 영역 또는 자식 요소 영역에서 마우스 포인터가 나갔을 때 발생합니다.",
    "validation" : [
        "컴포넌트 영역에서 마우스 포인터가 나갔을 때 이벤트가 발생하여야 합니다.",
        "컴포넌트 자식 영역에서 마우스 포인터가 나갔을 때 이벤트가 발생하여야 합니다.",
    ]
}



scwin.wf_sample_onwframeload = function () {
    let wf_body_left = wf_sample.getObj("wf_body_left");
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // comp 렌더링 할 객체 가져오기    
    // if (typeof wf_sample !== 'undefined') {
    //     let wf_body_sample = wf_sample.getObj("wf_body_sample");
    //     grp_comp = wf_body_sample.getObj("grp_comp");
    // }
    // else {        
    //     grp_comp = wf_body_sample.getObj("grp_comp"); 
    // }

    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // comp 생성 함수 호출    
    $c.gcm.createBasicGroup('', 'ev:onmouseout="scwin.target1_onmouseout"');    
}
